// Small Function Object (Functor) - Excellent Inlining Target
struct DataProcessor {
    const int bias;

    explicit DataProcessor(int b) : bias(b) {}

    // operator() is defined inside the class body.
    // This allows the compiler to easily inline the call site
    // (eliminating function call overhead, even in loops).
    int operator()(int x) const {
        return x * 2 + bias;
    }
};

// Example usage context:
DataProcessor p(5);
int result_a = p(10);   // Result: 25
// Compiler likely sees: result_a = 10 * 2 + 5;
// No actual function call instruction generated.
